#include <sys/types.h>
#include <sys/stat.h>
#include <sys/select.h>
#include <sys/resource.h>
#include <fcntl.h>
#include <unistd.h>
#include <poll.h>
#include <errno.h>
#include <inttypes.h>
#include <stdio.h>
#include <string.h>

static void result(const char *device, const char *operation, intmax_t value) {
    const int error = value < 0 ? errno : 0;
    printf("{\"device\":\"%s\",\"operation\":\"%s\",\"result\":%jd,\"errno\":%d}\n", device, operation, value, error);
}

static void cursor(const char *device, const char *operation, int descriptor, off_t offset, int origin) {
    errno = 0;
    result(device, operation, (intmax_t)lseek(descriptor, offset, origin));
}

static void sample(const char *device, const char *operation, int descriptor, size_t requested, off_t position, int positioned) {
    unsigned char buffer[7];
    memset(buffer, 0xa5, sizeof(buffer));
    errno = 0;
    const ssize_t count = positioned ? pread(descriptor, buffer + 2, requested, position) : read(descriptor, buffer + 2, requested);
    const int error = count < 0 ? errno : 0;
    int intact = 1;
    for (size_t index = 0; index < sizeof(buffer); index++) {
        if ((index < 2 || index >= 2 + requested) && buffer[index] != 0xa5) intact = 0;
    }
    int zeros = 1;
    if (strcmp(device, "zero") == 0 && count > 0) {
        for (ssize_t index = 0; index < count; index++) if (buffer[2 + index] != 0) zeros = 0;
    }
    printf("{\"device\":\"%s\",\"operation\":\"%s\",\"requested\":%zu,\"position\":%jd,\"count\":%jd,\"errno\":%d,\"boundsIntact\":%s,\"knownZero\":%s}\n",
        device, operation, requested, (intmax_t)position, (intmax_t)count, error, intact ? "true" : "false",
        strcmp(device, "zero") == 0 ? (zeros ? "true" : "false") : "null");
    volatile unsigned char *wipe = buffer;
    for (size_t index = 0; index < sizeof(buffer); index++) wipe[index] = 0;
}

static int inspect(const char *device) {
    char path[32];
    if (snprintf(path, sizeof(path), "/dev/%s", device) >= (int)sizeof(path)) return 10;
    struct stat admission;
    if (lstat(path, &admission) != 0 || !S_ISCHR(admission.st_mode)) return 11;
    const int flags = O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC;
    const int descriptor = open(path, flags);
    if (descriptor < 0) { result(device, "open", -1); return 12; }
    int independent = -1;
    int alias = -1;
    int status = 0;
    struct stat retained;
    if (fstat(descriptor, &retained) != 0 || !S_ISCHR(retained.st_mode)
        || retained.st_dev != admission.st_dev || retained.st_ino != admission.st_ino || retained.st_rdev != admission.st_rdev) {
        status = 13;
        goto close_descriptors;
    }
    independent = open(path, flags);
    if (independent < 0) { status = 14; goto close_descriptors; }
    alias = dup(descriptor);
    if (alias < 0) { status = 15; goto close_descriptors; }
    struct stat other;
    if (fstat(independent, &other) != 0 || !S_ISCHR(other.st_mode)
        || other.st_dev != retained.st_dev || other.st_ino != retained.st_ino || other.st_rdev != retained.st_rdev) {
        status = 16;
        goto close_descriptors;
    }
    printf("{\"device\":\"%s\",\"operation\":\"identity\",\"mode\":%ju,\"dev\":%ju,\"ino\":%ju,\"rdev\":%ju,\"size\":%jd,\"independentSameNode\":true}\n",
        device, (uintmax_t)retained.st_mode, (uintmax_t)retained.st_dev, (uintmax_t)retained.st_ino,
        (uintmax_t)retained.st_rdev, (intmax_t)retained.st_size);
    errno = 0;
    result(device, "access-read", access(path, R_OK));
    errno = 0;
    result(device, "access-write", access(path, W_OK));
    struct pollfd polling = { .fd = descriptor, .events = POLLIN, .revents = 0 };
    errno = 0;
    const int polled = poll(&polling, 1, 0);
    const int poll_error = polled < 0 ? errno : 0;
    printf("{\"device\":\"%s\",\"operation\":\"poll-read\",\"result\":%d,\"errno\":%d,\"revents\":%d}\n", device, polled, poll_error, polling.revents);
    fd_set reading;
    FD_ZERO(&reading);
    FD_SET(descriptor, &reading);
    struct timeval immediate = { .tv_sec = 0, .tv_usec = 0 };
    errno = 0;
    const int selected = select(descriptor + 1, &reading, NULL, NULL, &immediate);
    const int select_error = selected < 0 ? errno : 0;
    printf("{\"device\":\"%s\",\"operation\":\"select-read\",\"result\":%d,\"errno\":%d,\"ready\":%s}\n",
        device, selected, select_error, selected > 0 && FD_ISSET(descriptor, &reading) ? "true" : "false");
    cursor(device, "initial-position", descriptor, 0, SEEK_CUR);
    sample(device, "read-initial", descriptor, 1, 0, 0);
    cursor(device, "position-after-read", descriptor, 0, SEEK_CUR);
    cursor(device, "alias-after-read", alias, 0, SEEK_CUR);
    cursor(device, "independent-after-read", independent, 0, SEEK_CUR);
    cursor(device, "seek-set-7", descriptor, 7, SEEK_SET);
    sample(device, "read-after-set-7", descriptor, 1, 0, 0);
    cursor(device, "position-before-pread", descriptor, 0, SEEK_CUR);
    sample(device, "pread-0", descriptor, 3, 0, 1);
    sample(device, "pread-7", descriptor, 3, 7, 1);
    cursor(device, "position-after-pread", descriptor, 0, SEEK_CUR);
    cursor(device, "alias-after-pread", alias, 0, SEEK_CUR);
    cursor(device, "seek-end-0", descriptor, 0, SEEK_END);
    cursor(device, "seek-negative-1", descriptor, -1, SEEK_SET);
    cursor(device, "reset-position", descriptor, 0, SEEK_SET);
    errno = 0;
    result(device, "fsync-readonly", fsync(descriptor));
    errno = 0;
    result(device, "fullfsync-readonly", fcntl(descriptor, F_FULLFSYNC));
    struct stat final;
    if (fstat(descriptor, &final) != 0) { status = 17; goto close_descriptors; }
    printf("{\"device\":\"%s\",\"operation\":\"final-identity\",\"sameNode\":%s,\"size\":%jd}\n", device,
        final.st_dev == retained.st_dev && final.st_ino == retained.st_ino && final.st_rdev == retained.st_rdev && final.st_mode == retained.st_mode ? "true" : "false",
        (intmax_t)final.st_size);
close_descriptors:
    if (alias >= 0) { errno = 0; result(device, "close-alias", close(alias)); }
    if (independent >= 0) { errno = 0; result(device, "close-independent", close(independent)); }
    errno = 0;
    result(device, "close-main", close(descriptor));
    return status;
}

int main(int argc, char **argv) {
    (void)argv;
    if (argc != 1) return 2;
    const struct rlimit core = { .rlim_cur = 0, .rlim_max = 0 };
    if (setrlimit(RLIMIT_CORE, &core) != 0) return 3;
    alarm(3);
    const char *devices[] = { "null", "zero", "random", "urandom" };
    for (size_t index = 0; index < sizeof(devices) / sizeof(devices[0]); index++) {
        const int status = inspect(devices[index]);
        if (status != 0) return status;
    }
    alarm(0);
    return fflush(stdout) == 0 ? 0 : 4;
}

#include <sys/types.h>
#include <sys/stat.h>
#include <sys/resource.h>
#include <fcntl.h>
#include <unistd.h>
#include <dlfcn.h>
#include <errno.h>
#include <inttypes.h>
#include <stdio.h>
#include <string.h>

typedef int (*data_sync_function)(int);

static void record(const char *device, const char *profile, const char *operation, intmax_t value, int error) {
    printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"%s\",\"result\":%jd,\"errno\":%d}\n",
        device, profile, operation, value, error);
}

static intmax_t position(const char *device, const char *profile, const char *operation, int descriptor, off_t offset, int origin) {
    errno = 0;
    const off_t value = lseek(descriptor, offset, origin);
    const int error = value == (off_t)-1 ? errno : 0;
    record(device, profile, operation, (intmax_t)value, error);
    return (intmax_t)value;
}

static int same_node(const struct stat *first, const struct stat *second) {
    return S_ISCHR(second->st_mode) && first->st_dev == second->st_dev
        && first->st_ino == second->st_ino && first->st_rdev == second->st_rdev
        && first->st_mode == second->st_mode;
}

static int inspect(const char *device, const char *profile, int extra_flags, size_t *requested, data_sync_function data_sync) {
    if (strcmp(device, "null") != 0 && strcmp(device, "zero") != 0) return 10;
    char path[32];
    if (snprintf(path, sizeof(path), "/dev/%s", device) >= (int)sizeof(path)) return 11;
    struct stat admission;
    if (lstat(path, &admission) != 0 || !S_ISCHR(admission.st_mode)) return 12;
    const int flags = O_WRONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC | extra_flags;
    errno = 0;
    const int descriptor = open(path, flags);
    const int open_error = descriptor < 0 ? errno : 0;
    record(device, profile, "open", descriptor < 0 ? -1 : 0, open_error);
    if (descriptor < 0) return 13;
    int status = 0;
    struct stat retained;
    if (fstat(descriptor, &retained) != 0 || !same_node(&admission, &retained)) {
        status = 14;
        goto close_descriptor;
    }
    printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"identity\",\"mode\":%ju,\"dev\":%ju,\"ino\":%ju,\"rdev\":%ju,\"size\":%jd}\n",
        device, profile, (uintmax_t)retained.st_mode, (uintmax_t)retained.st_dev,
        (uintmax_t)retained.st_ino, (uintmax_t)retained.st_rdev, (intmax_t)retained.st_size);
    errno = 0;
    const int actual_flags = fcntl(descriptor, F_GETFL);
    const int flag_error = actual_flags < 0 ? errno : 0;
    printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"flags\",\"requested\":%d,\"actual\":%d,\"errno\":%d}\n",
        device, profile, flags, actual_flags, flag_error);
    if (actual_flags < 0 || (actual_flags & O_ACCMODE) != O_WRONLY || (actual_flags & extra_flags) != extra_flags) {
        status = 15;
        goto close_descriptor;
    }
    position(device, profile, "initial-position", descriptor, 0, SEEK_CUR);
    if (position(device, profile, "seek-set-7", descriptor, 7, SEEK_SET) != 7) {
        status = 16;
        goto close_descriptor;
    }
    const unsigned char payload = 0;
    for (int positioned = 0; positioned < 2; positioned++) {
        if (*requested >= 8) {
            status = 17;
            goto close_descriptor;
        }
        *requested += 1;
        errno = 0;
        const ssize_t count = positioned ? pwrite(descriptor, &payload, 1, 3) : write(descriptor, &payload, 1);
        const int write_error = count < 0 ? errno : 0;
        record(device, profile, positioned ? "pwrite-1-at-3" : "write-1", count, write_error);
        position(device, profile, positioned ? "position-after-pwrite" : "position-after-write", descriptor, 0, SEEK_CUR);
    }
    errno = 0;
    const int synced = fsync(descriptor);
    record(device, profile, "fsync", synced, synced < 0 ? errno : 0);
    if (data_sync != NULL) {
        errno = 0;
        const int data_synced = data_sync(descriptor);
        record(device, profile, "fdatasync-native-symbol", data_synced, data_synced < 0 ? errno : 0);
    } else {
        printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"fdatasync\",\"availability\":\"missing-native-symbol\",\"fallback\":false}\n", device, profile);
    }
    const off_t lengths[] = { 0, 1, 4096 };
    for (size_t index = 0; index < sizeof(lengths) / sizeof(lengths[0]); index++) {
        errno = 0;
        const int truncated = ftruncate(descriptor, lengths[index]);
        const int truncate_error = truncated < 0 ? errno : 0;
        struct stat after;
        if (fstat(descriptor, &after) != 0 || !same_node(&retained, &after)) {
            status = 18;
            goto close_descriptor;
        }
        printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"ftruncate\",\"length\":%jd,\"result\":%d,\"errno\":%d,\"size\":%jd,\"sameNode\":true}\n",
            device, profile, (intmax_t)lengths[index], truncated, truncate_error, (intmax_t)after.st_size);
        position(device, profile, "position-after-ftruncate", descriptor, 0, SEEK_CUR);
    }
close_descriptor:
    errno = 0;
    const int closed = close(descriptor);
    record(device, profile, "close", closed, closed < 0 ? errno : 0);
    return closed != 0 ? 19 : status;
}

int main(int argc, char **argv) {
    (void)argv;
    if (argc != 1) return 2;
    const struct rlimit core = { .rlim_cur = 0, .rlim_max = 0 };
    if (setrlimit(RLIMIT_CORE, &core) != 0) return 3;
    alarm(3);
    dlerror();
    data_sync_function data_sync = (data_sync_function)dlsym(RTLD_DEFAULT, "fdatasync");
    const char *symbol_error = dlerror();
    if (symbol_error != NULL) data_sync = NULL;
    printf("{\"operation\":\"fdatasync-symbol\",\"available\":%s,\"lookupError\":%s,\"fallback\":false}\n",
        data_sync != NULL ? "true" : "false", symbol_error != NULL ? "true" : "false");
    if (data_sync != NULL) {
        Dl_info symbol_info;
        if (dladdr((void *)data_sync, &symbol_info) == 0 || symbol_info.dli_fname == NULL || symbol_info.dli_sname == NULL) return 4;
        printf("{\"operation\":\"fdatasync-symbol-provider\",\"image\":\"%s\",\"symbol\":\"%s\"}\n", symbol_info.dli_fname, symbol_info.dli_sname);
    }
    printf("{\"operation\":\"constants\",\"O_APPEND\":%d,\"O_SYNC\":%d,\"O_DSYNC\":%d,\"O_WRONLY\":%d}\n", O_APPEND, O_SYNC, O_DSYNC, O_WRONLY);
    const char *devices[] = { "null", "zero" };
    const char *profiles[] = { "plain", "append", "sync", "dsync" };
    const int flags[] = { 0, O_APPEND, O_SYNC, O_DSYNC };
    for (size_t device_index = 0; device_index < sizeof(devices) / sizeof(devices[0]); device_index++) {
        size_t requested = 0;
        for (size_t profile_index = 0; profile_index < sizeof(profiles) / sizeof(profiles[0]); profile_index++) {
            const int status = inspect(devices[device_index], profiles[profile_index], flags[profile_index], &requested, data_sync);
            if (status != 0) return status;
        }
        printf("{\"device\":\"%s\",\"operation\":\"total-requested-write-bytes\",\"count\":%zu}\n", devices[device_index], requested);
    }
    alarm(0);
    return fflush(stdout) == 0 ? 0 : 5;
}

