#include <unistd.h>
#include <errno.h>
#include <inttypes.h>
#include <stdio.h>
#include <string.h>

static void record(const char *device, const char *profile, const char *operation, intmax_t value, int error) {
    printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"%s\",\"result\":%jd,\"errno\":%d}\n",
        device, profile, operation, value, error);
}

static off_t position(const char *device, const char *profile, const char *operation, int descriptor, off_t offset, int origin) {
    errno = 0;
    const off_t value = lseek(descriptor, offset, origin);
    const int error = value == (off_t)-1 ? errno : 0;
    record(device, profile, operation, value, error);
    return value;
}

static int same_node(const struct stat *first, const struct stat *second) {
    return S_ISCHR(second->st_mode) && first->st_dev == second->st_dev
        && first->st_ino == second->st_ino && first->st_rdev == second->st_rdev
        && first->st_mode == second->st_mode;
}

static int inspect(const char *device, const char *profile, int append, size_t *requested, size_t *completed, struct stat *identity) {
    if (strcmp(device, "random") != 0 && strcmp(device, "urandom") != 0) return 10;
    char path[32];
    if (snprintf(path, sizeof(path), "/dev/%s", device) >= (int)sizeof(path)) return 11;
    struct stat admission;
    if (lstat(path, &admission) != 0 || !S_ISCHR(admission.st_mode)) return 12;
    if (*requested > 0 && !same_node(identity, &admission)) return 13;
    const int flags = O_WRONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC | (append ? O_APPEND : 0);
    errno = 0;
    const int descriptor = open(path, flags);
    record(device, profile, "open", descriptor < 0 ? -1 : 0, descriptor < 0 ? errno : 0);
    if (descriptor < 0) return 14;
    int status = 0;
    struct stat retained;
    if (fstat(descriptor, &retained) != 0 || !same_node(&admission, &retained)) {
        status = 15;
        goto close_descriptor;
    }
    *identity = retained;
    printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"identity\",\"mode\":%ju,\"dev\":%ju,\"ino\":%ju,\"rdev\":%ju,\"size\":%jd}\n",
        device, profile, (uintmax_t)retained.st_mode, (uintmax_t)retained.st_dev,
        (uintmax_t)retained.st_ino, (uintmax_t)retained.st_rdev, (intmax_t)retained.st_size);
    errno = 0;
    const int actual_flags = fcntl(descriptor, F_GETFL);
    record(device, profile, "flags", actual_flags, actual_flags < 0 ? errno : 0);
    if (actual_flags < 0 || (actual_flags & O_ACCMODE) != O_WRONLY || !!(actual_flags & O_APPEND) != append) {
        status = 16;
        goto close_descriptor;
    }
    position(device, profile, "initial-position", descriptor, 0, SEEK_CUR);
    if (position(device, profile, "seek-set-7", descriptor, 7, SEEK_SET) != 7) {
        status = 17;
        goto close_descriptor;
    }
    const unsigned char fixed_payload = 0;
    for (int positioned = 0; positioned < 2; positioned++) {
        struct stat before_io;
        if (fstat(descriptor, &before_io) != 0 || !same_node(&retained, &before_io)) {
            status = 18;
            goto close_descriptor;
        }
        const off_t before_position = position(device, profile, positioned ? "before-pwrite" : "before-write", descriptor, 0, SEEK_CUR);
        if (before_position < 0 || *requested >= 4) {
            status = 19;
            goto close_descriptor;
        }
        *requested += 1;
        errno = 0;
        const ssize_t count = positioned ? pwrite(descriptor, &fixed_payload, 1, 3) : write(descriptor, &fixed_payload, 1);
        const int error = count < 0 ? errno : 0;
        if (count > 0) *completed += (size_t)count;
        printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"%s\",\"requested\":1,\"positioned\":%s,\"requestedOffset\":%jd,\"returned\":%jd,\"completed\":%jd,\"error\":%s,\"errno\":%d}\n",
            device, profile, positioned ? "pwrite" : "write", positioned ? "true" : "false", (intmax_t)(positioned ? 3 : before_position),
            (intmax_t)count, (intmax_t)(count > 0 ? count : 0), count < 0 ? "true" : "false", error);
        position(device, profile, positioned ? "after-pwrite" : "after-write", descriptor, 0, SEEK_CUR);
    }
    struct stat after_io;
    if (fstat(descriptor, &after_io) != 0 || !same_node(&retained, &after_io)) {
        status = 20;
        goto close_descriptor;
    }
    printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"final-identity\",\"sameNode\":true,\"size\":%jd}\n", device, profile, (intmax_t)after_io.st_size);
close_descriptor:
    errno = 0;
    const int closed = close(descriptor);
    record(device, profile, "close", closed, closed < 0 ? errno : 0);
    return closed != 0 ? 21 : status;
}

int main(int argc, char **argv) {
    (void)argv;
    if (argc != 1) return 2;
    const struct rlimit core = { .rlim_cur = 0, .rlim_max = 0 };
    if (setrlimit(RLIMIT_CORE, &core) != 0) return 3;
    alarm(3);
    printf("{\"operation\":\"constants\",\"EPERM\":%d,\"O_APPEND\":%d,\"O_WRONLY\":%d}\n", EPERM, O_APPEND, O_WRONLY);
    const char *devices[] = { "random", "urandom" };
    for (size_t index = 0; index < sizeof(devices) / sizeof(devices[0]); index++) {
        size_t requested = 0;
        size_t completed = 0;
        struct stat identity;
        int status = inspect(devices[index], "plain", 0, &requested, &completed, &identity);
        if (status != 0) return status;
        status = inspect(devices[index], "append", 1, &requested, &completed, &identity);
        if (status != 0) return status;
        printf("{\"device\":\"%s\",\"operation\":\"totals\",\"requested\":%zu,\"completed\":%zu}\n", devices[index], requested, completed);
    }
    alarm(0);
    return fflush(stdout) == 0 ? 0 : 4;
}

