static void result(const char *device, const char *profile, const char *operation, intmax_t value, int error) {
    printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"%s\",\"result\":%jd,\"errno\":%d}\n", device, profile, operation, value, error);
