    return S_ISCHR(second->st_mode) && first->st_dev == second->st_dev && first->st_ino == second->st_ino
        && first->st_rdev == second->st_rdev && first->st_mode == second->st_mode;
}

static int inspect(const char *device, const char *profile, int access, int extra_flags, int zero_io, data_sync_function data_sync) {
    char path[32];
    if (snprintf(path, sizeof(path), "/dev/%s", device) >= (int)sizeof(path)) return 10;
    struct stat admission;
    if (lstat(path, &admission) != 0 || !S_ISCHR(admission.st_mode)) return 11;
    const int flags = access | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC | extra_flags;
    errno = 0;
    const int descriptor = open(path, flags);
    result(device, profile, "open", descriptor < 0 ? -1 : 0, descriptor < 0 ? errno : 0);
    if (descriptor < 0) return 12;
    int status = 0;
    struct stat retained;
    if (fstat(descriptor, &retained) != 0 || !same_node(&admission, &retained)) {
        status = 13;
        goto close_descriptor;
    }
    printf("{\"device\":\"%s\",\"profile\":\"%s\",\"operation\":\"identity\",\"mode\":%ju,\"dev\":%ju,\"ino\":%ju,\"rdev\":%ju,\"size\":%jd}\n",
        device, profile, (uintmax_t)retained.st_mode, (uintmax_t)retained.st_dev, (uintmax_t)retained.st_ino, (uintmax_t)retained.st_rdev, (intmax_t)retained.st_size);
    errno = 0;
    const int observed_flags = fcntl(descriptor, F_GETFL);
    result(device, profile, "flags", observed_flags, observed_flags < 0 ? errno : 0);
    if (observed_flags < 0 || (observed_flags & O_ACCMODE) != access || (observed_flags & extra_flags) != extra_flags) {
        status = 14;
        goto close_descriptor;
    }
    errno = 0;
    const off_t positioned = lseek(descriptor, 7, SEEK_SET);
    result(device, profile, "seek-set-7", positioned, positioned == (off_t)-1 ? errno : 0);
    if (positioned != 7) {
        status = 15;
        goto close_descriptor;
    }
    if (zero_io) {
        for (int writing = 0; writing < 2; writing++) {
            struct stat before_io;
            if (fstat(descriptor, &before_io) != 0 || !same_node(&retained, &before_io)) {
                status = 16;
                goto close_descriptor;
            }
            errno = 0;
            const off_t before = lseek(descriptor, 0, SEEK_CUR);
            result(device, profile, writing ? "before-write-zero" : "before-read-zero", before, before == (off_t)-1 ? errno : 0);
            if (before < 0) {
                status = 17;
                goto close_descriptor;
            }
            unsigned char sentinel = 0xa5;
            errno = 0;
            const ssize_t count = writing ? write(descriptor, &sentinel, 0) : read(descriptor, &sentinel, 0);
            const int error = count < 0 ? errno : 0;
